<?php foreach ($rows as $i=>$item): ?><?php $selectedProductLabel = ''; foreach ($sellable as $candidate) { if ((string)$candidate['id'] === (string)$item['producto_id']) { $selectedProductLabel = $candidate['codigo'].' · '.$candidate['nombre']; break; } } ?><div class="sale-line grid gap-3 rounded-lg border border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-4"><div class="lg:col-span-2"><span class="text-sm font-semibold">Producto</span><input type="hidden" name="items[<?= $i ?>][producto_id]" value="<?= e($item['producto_id']) ?>" class="product-id"><button type="button" class="open-product-modal mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 text-left text-sm font-normal"><?= e($selectedProductLabel ?: 'Buscar producto…') ?></button></div><label class="text-sm font-semibold">Cantidad<input required type="number" min="0.001" step="0.001" name="items[<?= $i ?>][cantidad]" value="<?= e($item['cantidad']) ?>" class="sale-quantity mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><label class="text-sm font-semibold">Precio unitario (S/)<input required type="number" min="0" step="0.01" name="items[<?= $i ?>][precio_unitario]" value="<?= e($item['precio_unitario']) ?>" <?= $canDiscount?'':'readonly' ?> class="sale-price mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><div class="flex items-center justify-between lg:col-span-4"><span class="line-stock text-xs text-slate-500"></span><span class="line-total text-sm font-semibold"></span><button type="button" class="remove-row text-sm font-semibold text-red-700">Quitar</button></div></div><?php endforeach; ?></div>
<div class="mt-5 flex justify-end border-t border-slate-100 pt-4"><div class="text-right"><div class="text-sm text-slate-500">Total</div><div id="sale-total" class="text-2xl font-bold text-slate-900">S/ 0.00</div></div></div><?php if ($canDiscount): ?><p class="mt-2 text-right text-xs text-emerald-800">Tienes autorización para ajustar precios y aplicar descuentos.</p><?php endif; ?></div>
