<dialog id="product-modal" class="w-[min(92vw,48rem)] rounded-xl p-0 shadow-2xl backdrop:bg-slate-900/50"><div class="border-b border-slate-200 p-4"><div class="flex items-center justify-between"><h2 class="text-lg font-bold">Seleccionar producto</h2><button type="button" class="close-product-modal rounded px-3 py-1 text-slate-600" aria-label="Cerrar">✕</button></div><input id="product-search" type="search" placeholder="Buscar por código o nombre…" class="mt-3 min-h-11 w-full rounded-lg border border-slate-300 px-3 text-sm"></div><div class="max-h-[60vh] overflow-y-auto p-3"><div id="product-options" class="divide-y divide-slate-100"><?php foreach ($sellable as $product): ?><button type="button" class="choose-product flex w-full items-center justify-between gap-3 rounded-lg p-3 text-left hover:bg-emerald-50" data-id="<?= e($product['id']) ?>" data-label="<?= e($product['codigo'].' · '.$product['nombre']) ?>" data-price="<?= e($product['precio_venta']) ?>" data-stock="<?= e($product['stock_vendible']) ?>" data-search="<?= e(mb_strtolower($product['codigo'].' '.$product['nombre'])) ?>"><span><strong class="block text-sm"><?= e($product['nombre']) ?></strong><span class="text-xs text-slate-500"><?= e($product['codigo'].' · Stock '.$product['stock_vendible'].' '.$product['unidad_medida']) ?></span></span><span class="text-right text-sm"><strong class="block">S/ <?= e(number_format((float)$product['precio_venta'],2)) ?></strong><span class="text-xs text-emerald-800">Seleccionar</span></span></button><?php endforeach; ?></div><p id="no-products" class="hidden p-6 text-center text-sm text-slate-500">No se encontraron productos.</p></div></dialog>
<script>
(() => {
 const container = document.getElementById('sale-lines');
 const modal = document.getElementById('product-modal'); let activeRow = null;
 const money = value => 'S/ ' + (Number(value)||0).toFixed(2);
 const refresh = row => { const id=row.querySelector('.product-id').value, option=[...document.querySelectorAll('.choose-product')].find(button=>button.dataset.id===id), price=row.querySelector('.sale-price'); if(option){ if(!price.value) price.value=Number(option.dataset.price).toFixed(2); row.querySelector('.line-stock').textContent='Stock vigente disponible: '+Number(option.dataset.stock).toFixed(3); } else row.querySelector('.line-stock').textContent=''; row.querySelector('.line-total').textContent=money((Number(row.querySelector('.sale-quantity').value)||0)*(Number(price.value)||0)); };
 const recalc = () => { let total=0; container.querySelectorAll('.sale-line').forEach(row=>{ refresh(row); total+=(Number(row.querySelector('.sale-quantity').value)||0)*(Number(row.querySelector('.sale-price').value)||0); }); document.getElementById('sale-total').textContent=money(total); };
 const reindex = () => [...container.querySelectorAll('.sale-line')].forEach((row,i)=>row.querySelectorAll('[name]').forEach(el=>el.name=el.name.replace(/items\[\d+\]/,`items[${i}]`)));
 document.getElementById('add-row').addEventListener('click',()=>{const row=container.querySelector('.sale-line').cloneNode(true);row.querySelectorAll('input').forEach(input=>input.value='');row.querySelector('.open-product-modal').textContent='Buscar producto…';container.appendChild(row);reindex();recalc();});
 container.addEventListener('click',event=>{if(event.target.closest('.open-product-modal')){activeRow=event.target.closest('.sale-line');modal.showModal();document.getElementById('product-search').value='';filterProducts('');document.getElementById('product-search').focus();}});
 document.getElementById('product-options').addEventListener('click',event=>{const choice=event.target.closest('.choose-product');if(!choice||!activeRow)return;activeRow.querySelector('.product-id').value=choice.dataset.id;activeRow.querySelector('.open-product-modal').textContent=choice.dataset.label;activeRow.querySelector('.sale-price').value=Number(choice.dataset.price).toFixed(2);modal.close();recalc();});
 document.getElementById('product-search').addEventListener('input',event=>filterProducts(event.target.value));
 function filterProducts(query){let shown=0;document.querySelectorAll('.choose-product').forEach(button=>{const match=button.dataset.search.includes(query.trim().toLowerCase());button.hidden=!match;if(match)shown++;});document.getElementById('no-products').classList.toggle('hidden',shown>0);}
 document.querySelectorAll('.close-product-modal').forEach(button=>button.addEventListener('click',()=>modal.close()));
 container.addEventListener('input',recalc);
 container.addEventListener('click',event=>{if(event.target.classList.contains('remove-row')&&container.querySelectorAll('.sale-line').length>1){event.target.closest('.sale-line').remove();reindex();recalc();}});
 recalc();
})();
</script><?php endif; ?></section>
